  const studentSteps = { [AppState.STUDENT_ENTRY]: 1, [AppState.STUDENT_WELCOME]: 2, [AppState.STUDENT_PRIVACY]: 3, [AppState.STUDENT_AGREEMENT]: 4, [AppState.STUDENT_PROFILE]: 5, [AppState.STUDENT_MISSION]: 6, [AppState.STUDENT_ARTIFACT]: 7, [AppState.STUDENT_READY]: 7 };
  const total = isStudentState(state) ? 7 : 11;
  const position = isStudentState(state) ? studentSteps[state] : current;
  progressText.textContent = state === AppState.INTRO ? "" : state === AppState.FAMILY_SUMMARY ? "Panel familiar" : state === AppState.STUDENT_READY ? "Listo" : isStudentState(state) ? `Tu acceso · ${position} de ${total}` : `${position} de ${total}`;
