function transitionTo(nextState) {
  if (nextState === currentState && screen.innerHTML) return;
  clearTimeout(introTimer); transitionVeil.classList.remove("is-opening"); transitionVeil.classList.add("is-closing"); screen.classList.remove("is-entering"); screen.classList.add("is-leaving");
  setTimeout(() => { currentState = nextState; render(); screen.classList.remove("is-leaving"); screen.classList.add("is-entering"); transitionVeil.classList.remove("is-closing"); transitionVeil.classList.add("is-opening"); setTimeout(() => transitionVeil.classList.remove("is-opening"), 720); }, 380);
}

