function renderStudentPrivacy() { return `<div class="layout single student-centered"><div class="copy student-copy"><span class="kicker reveal"><span class="pulse-dot"></span> Tu privacidad</span><h2 class="reveal" id="screen-title">Tu espacio con ADA es para pensar con honestidad.</h2><p class="lead reveal">Tus papás no ven por defecto toda tu conversación ni tus respuestas privadas.</p><div class="student-info-grid reveal"><article><strong>Lo que sí puede compartirse</strong><p>Un artefacto que tú validas al terminar una misión puede ayudar a abrir una conversación en casa.</p></article><article><strong>Cuando necesitas ayuda</strong><p>Si algo necesita apoyo adulto, ADA puede ayudarte a pedirlo sin exponerte de más.</p></article></div><div class="actions reveal"><button class="btn cyan" data-next="${AppState.STUDENT_AGREEMENT}">Hacer mi acuerdo</button></div></div></div>`; }
function renderStudentAgreement() { return `<div class="agreement-layout student-agreement" id="agreementRoot" style="--hold-alpha:0"><div class="agreement-visual reveal"><img src="${ASSETS.agreement}" alt="Dos manos haciendo un acuerdo de confianza"></div><div class="copy"><span class="kicker reveal"><span class="pulse-dot"></span> Tu acuerdo</span><h2 class="reveal" id="screen-title">Un acuerdo para pensar de verdad.</h2><p class="lead reveal">Este espacio es privado para que puedas responder sin actuar perfecto.</p><p class="body-copy reveal">ADA no necesita que digas “lo correcto”. Necesita que pienses con calma, pruebes ideas y digas cuando algo no te queda claro. Si algo te preocupa o se siente demasiado grande para resolverlo solo, puedes pedir ayuda.</p><section class="agreement-card reveal"><h3>Mi acuerdo</h3><p class="body-copy">Voy a responder con honestidad, aunque no suene perfecto.<br><br>Voy a intentar pensar antes de contestar rápido.<br><br>Si algo me preocupa o necesito ayuda, puedo decirlo.</p></section><div class="hold-wrap reveal"><button class="hold-button" id="holdButton" type="button" aria-label="Mantén presionado para guardar tu acuerdo"><span id="holdLabel">Lo hago</span></button><p class="body-copy">Mantén presionado para guardar tu acuerdo.</p></div></div></div>`; }
function interestChip(value, label) { return `<button type="button" class="interest-chip" data-interest="${value}" aria-pressed="${onboardingData.studentInterests.includes(value)}">${label}</button>`; }
function renderStudentProfile() { const name = escapeHtml(onboardingData.studentName || onboardingData.childName || ""); return `<div class="layout single student-centered"><form class="copy student-copy form-grid" id="studentProfileForm"><span class="kicker reveal"><span class="pulse-dot"></span> Ajustemos la conversación</span><h2 class="reveal" id="screen-title">Para ajustar la conversación, necesito conocerte un poco.</h2><div class="field reveal"><label for="studentName">¿Cómo quieres que te diga?</label><input class="text-input" id="studentName" value="${name}" placeholder="Tu nombre"></div><div class="field reveal"><span class="choice-label">¿Qué sueles hacer en línea?</span><div class="interest-grid" role="group" aria-label="Intereses">${interestChip("crear", "Crear")}${interestChip("jugar", "Jugar")}${interestChip("convivir", "Convivir")}${interestChip("explorar", "Explorar")}${interestChip("retos", "Resolver retos")}${interestChip("aprender", "Aprender")}</div></div><div class="actions reveal"><button class="btn cyan" id="studentProfileCta" type="submit" disabled>Guardar</button></div></form></div>`; }
function renderStudentMission() { return `<div class="layout single student-centered"><div class="copy student-copy"><span class="kicker reveal"><span class="pulse-dot"></span> Una misión a la vez</span><h2 class="reveal" id="screen-title">Cada misión empieza con una situación.</h2><p class="display-subtitle reveal">No con una respuesta correcta.</p><p class="lead reveal">ADA te mostrará un dilema, un dato breve o una escena parecida a algo que puede pasar en internet.</p><div class="mission-steps reveal"><span><b>1</b> Piensas</span><span><b>2</b> Respondes</span><span><b>3</b> Ajustas</span><span><b>4</b> Cierras con una idea propia</span></div><ul class="student-promise reveal"><li>No tienes que sonar perfecto.</li><li>Puedes cambiar de opinión.</li><li>No publicar también puede ser una decisión.</li></ul><div class="actions reveal"><button class="btn cyan" data-next="${AppState.STUDENT_ARTIFACT}">Crear mi artefacto</button></div></div></div>`; }
