function bindStateEvents() {
  if (currentState === AppState.INTRO) { document.querySelector(".intro-skip").addEventListener("click", () => transitionTo(AppState.WELCOME)); introTimer = setTimeout(() => transitionTo(AppState.WELCOME), INTRO_DURATION); return; }
  screen.querySelectorAll("[data-next]").forEach(button => button.addEventListener("click", () => transitionTo(button.dataset.next)));
  screen.querySelectorAll("[data-edit-child]").forEach(button => button.addEventListener("click", () => { editingChild = true; transitionTo(AppState.ADD_CHILD); }));
  screen.querySelectorAll("[data-student-preview]").forEach(button => button.addEventListener("click", () => transitionTo(AppState.STUDENT_ENTRY)));
  if (currentState === AppState.WELCOME) bindWelcome();
  if (currentState === AppState.ARTIFACT) bindArtifact(); if (currentState === AppState.ADD_CHILD) bindAddChild(); if (currentState === AppState.PRIMARY_PROFILE) bindPrimaryProfile(); if (currentState === AppState.STUDENT_INVITE) bindStudentInvite(); if (currentState === AppState.AGREEMENT) bindAgreement(); if (currentState === AppState.STUDENT_AGREEMENT) bindAgreement(AppState.STUDENT_PROFILE, "Acuerdo guardado.", "studentAgreementAccepted"); if (currentState === AppState.STUDENT_ENTRY) bindStudentEntry(); if (currentState === AppState.STUDENT_PROFILE) bindStudentProfile();
  if (currentState === AppState.FAMILY_SUMMARY) bindFamilyReport();
  if (currentState === AppState.STUDENT_READY) document.querySelector("#startMission").addEventListener("click", () => announce("La primera misión estará disponible en la experiencia del alumno."));
}
function bindWelcome() {
  const audioToggle = document.querySelector("[data-ada-audio]");
  const video = document.querySelector(".ada-video");
  if (!audioToggle || !video) return;
  audioToggle.addEventListener("click", () => {
    video.muted = !video.muted;
    const isOn = !video.muted;
    audioToggle.textContent = isOn ? "Silenciar" : "Activar audio";
    audioToggle.setAttribute("aria-pressed", String(isOn));
    if (isOn) video.play().catch(() => {});
  });
}
function bindStudentEntry() {
  const cta = document.querySelector("#studentEntryCta");
  screen.querySelectorAll("[data-student-stage]").forEach(button => button.addEventListener("click", () => {
    onboardingData.stage = button.dataset.studentStage;
    screen.querySelectorAll("[data-student-stage]").forEach(item => item.setAttribute("aria-pressed", String(item === button)));
  }));
  cta.addEventListener("click", () => transitionTo(AppState.STUDENT_WELCOME));
}
function bindStudentProfile() {
  const form = document.querySelector("#studentProfileForm"), name = document.querySelector("#studentName"), cta = document.querySelector("#studentProfileCta");
  function sync() { onboardingData.studentName = name.value.trim(); cta.disabled = !(onboardingData.studentName && onboardingData.studentInterests.length); }
  name.addEventListener("input", sync);
  screen.querySelectorAll("[data-interest]").forEach(button => button.addEventListener("click", () => {
    const interest = button.dataset.interest;
    onboardingData.studentInterests = onboardingData.studentInterests.includes(interest) ? onboardingData.studentInterests.filter(item => item !== interest) : [...onboardingData.studentInterests, interest];
    button.setAttribute("aria-pressed", String(onboardingData.studentInterests.includes(interest)));
    sync();
  }));
  form.addEventListener("submit", event => { event.preventDefault(); if (!cta.disabled) transitionTo(AppState.STUDENT_MISSION); });
  sync();
}
function bindFamilyReport() {
  screen.querySelectorAll("[data-report-student]").forEach(button => button.addEventListener("click", () => { onboardingData.reportStudent = button.dataset.reportStudent; render(); }));
  screen.querySelectorAll("[data-report-view]").forEach(button => button.addEventListener("click", () => { onboardingData.reportVisual = button.dataset.reportView; render(); }));
  screen.querySelectorAll("[data-report-accordion]").forEach(button => button.addEventListener("click", () => {
    const detail = document.querySelector(`#${button.dataset.reportAccordion}Detail`);
    const open = button.getAttribute("aria-expanded") === "true";
    button.setAttribute("aria-expanded", String(!open));
    detail.hidden = open;
  }));
}
function bindArtifact() { screen.querySelectorAll("[data-artifact-age]").forEach(button => button.addEventListener("click", () => { onboardingData.selectedArtifactAge = button.dataset.artifactAge; screen.querySelectorAll("[data-artifact-age]").forEach(item => item.setAttribute("aria-pressed", String(item === button))); document.querySelector("#artifactExample").textContent = `“${artifactExample()}”`; })); }
function bindAddChild() {
  const form = document.querySelector("#childForm"), nameInput = document.querySelector("#childName"), cta = document.querySelector("#addChildCta");
  function syncCta() { onboardingData.childName = nameInput.value.trim(); cta.disabled = !(onboardingData.childName && onboardingData.stage && onboardingData.grade); cta.textContent = editingChild ? "Guardar cambios" : onboardingData.stage === "primary" ? "Crear perfil acompañado" : "Preparar invitación"; }
  nameInput.addEventListener("input", syncCta);
  screen.querySelectorAll("[data-stage]").forEach(button => button.addEventListener("click", () => { onboardingData.stage = button.dataset.stage; onboardingData.grade = ""; document.querySelector("#gradeField").innerHTML = renderGradeChoices(); screen.querySelectorAll("[data-stage]").forEach(item => item.setAttribute("aria-pressed", String(item === button))); bindGradeButtons(syncCta); syncCta(); }));
  bindGradeButtons(syncCta); form.addEventListener("submit", event => { event.preventDefault(); if (!cta.disabled) { editingChild = false; transitionTo(onboardingData.stage === "primary" ? AppState.PRIMARY_PROFILE : AppState.STUDENT_INVITE); } }); syncCta();
}
function bindGradeButtons(onChange) { screen.querySelectorAll("[data-grade]").forEach(button => button.addEventListener("click", () => { onboardingData.grade = button.dataset.grade; screen.querySelectorAll("[data-grade]").forEach(item => item.setAttribute("aria-pressed", String(item === button))); onChange(); })); }
function bindPrimaryProfile() { const createButton = document.querySelector("#createProfile"); screen.querySelectorAll("[data-avatar]").forEach(button => button.addEventListener("click", () => { onboardingData.avatar = button.dataset.avatar; screen.querySelectorAll("[data-avatar]").forEach(item => item.setAttribute("aria-pressed", String(item === button))); document.querySelector("#summaryAvatar").src = onboardingData.avatar; createButton.disabled = false; })); createButton.addEventListener("click", () => { document.querySelector("#profileReady").classList.add("is-visible"); announce("Perfil listo. Ahora verás cómo funciona tu panel familiar."); setTimeout(() => transitionTo(AppState.FAMILY_DASHBOARD_INTRO), 1100); }); }
function bindStudentInvite() { screen.querySelectorAll("[data-method]").forEach(button => button.addEventListener("click", () => { onboardingData.inviteMethod = button.dataset.method; document.querySelector("#invitePanel").innerHTML = renderInvitePanel(); screen.querySelectorAll("[data-method]").forEach(item => item.classList.toggle("is-selected", item === button)); bindInvitePanelControls(); })); bindInvitePanelControls(); }
function bindInvitePanelControls() {
  const copyLink = document.querySelector("#copyLink"); if (copyLink) copyLink.addEventListener("click", async () => { try { await navigator.clipboard.writeText(JOIN_URL); } catch { window.prompt("Copia este enlace:", JOIN_URL); } const status = document.querySelector("#copyStatus"); status.classList.add("is-visible"); copyLink.textContent = "Copiado ✓"; announce("Enlace copiado."); setTimeout(() => { status.classList.remove("is-visible"); copyLink.textContent = "Copiar enlace"; }, 1500); });
  const simulateEmail = document.querySelector("#simulateEmail"); if (simulateEmail) simulateEmail.addEventListener("click", () => { simulateEmail.disabled = true; simulateEmail.textContent = "Preparando…"; setTimeout(() => { document.querySelector("#emailStatus").classList.add("is-visible"); simulateEmail.textContent = "Preparar invitación"; simulateEmail.disabled = false; announce("Invitación preparada."); }, 620); });
  const openWhatsapp = document.querySelector("#openWhatsapp"); if (openWhatsapp) openWhatsapp.addEventListener("click", () => window.open(`https://wa.me/?text=${encodeURIComponent(invitationMessage())}`, "_blank", "noopener,noreferrer"));
}
function bindAgreement(nextState = AppState.AGREEMENT_COMPLETE, completeMessage = "Promesa guardada.", acceptedField = "agreementAccepted") {
  cancelAnimationFrame(holdFrame); holdLocked = false; holdProgress = 0; holdStart = 0;
  const root = document.querySelector("#agreementRoot"), button = document.querySelector("#holdButton"), label = document.querySelector("#holdLabel");
  function setProgress(value) { holdProgress = Math.max(0, Math.min(1, value)); button.style.setProperty("--hold-progress", (holdProgress * 100).toFixed(2)); root.style.setProperty("--hold-alpha", holdProgress.toFixed(3)); }
  function complete() { holdLocked = true; onboardingData[acceptedField] = true; setProgress(1); button.classList.add("is-complete"); label.textContent = "✓"; announce(completeMessage); navigator.vibrate?.(30); setTimeout(() => transitionTo(nextState), 820); }
  function tick(now) { if (!holdStart || holdLocked) return; const progress = (now - holdStart) / HOLD_DURATION; setProgress(progress); if (progress >= 1) return complete(); holdFrame = requestAnimationFrame(tick); }
  function start() { if (!holdLocked) { cancelAnimationFrame(holdFrame); holdStart = performance.now() - holdProgress * HOLD_DURATION; holdFrame = requestAnimationFrame(tick); } }
  function cancel() { if (holdLocked) return; cancelAnimationFrame(holdFrame); holdStart = 0; const initial = holdProgress, started = performance.now(); function easeBack(now) { const t = Math.min(1, (now - started) / 320); setProgress(initial * (1 - t)); if (t < 1) requestAnimationFrame(easeBack); } requestAnimationFrame(easeBack); }
  button.addEventListener("pointerdown", event => { button.setPointerCapture?.(event.pointerId); start(); }); ["pointerup", "pointercancel", "pointerleave"].forEach(event => button.addEventListener(event, cancel)); button.addEventListener("keydown", event => { if (event.key === " " || event.key === "Enter") { event.preventDefault(); start(); } }); button.addEventListener("keyup", event => { if (event.key === " " || event.key === "Enter") { event.preventDefault(); cancel(); } });
}
